#[cfg(zopro_unscaled_mixed_g1)]
if core::mem::size_of::<C::Base>() == core::mem::size_of::<Fq>() {
    // HMV mixed addition: scalar Fq square and multiply share a backend.
    // Keep the existing complete guards; ordinary output uses half the old Z.
    let h = u2 - self.x;
    let r = s2 - self.y;
    let hh = h.square();
    let hhh = h * hh;
    let v = self.x * hh;
    let x = r.square() - hhh - v.double();
    let y = r * (v - x) - self.y * hhh;
    let z = self.z * h;
    return Self::new(x, y, z);
}
